  `project_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '신규' COMMENT '프로젝트 구분 (신규/MOD)',
  `panel_corners_excluded` tinyint(1) DEFAULT '1' COMMENT '1,11번 패널 제외 여부 (0=포함, 1=제외)',
  `production_height` int(11) DEFAULT NULL COMMENT '제작 높이 (mm)',
