CREATE ALGORITHM=UNDEFINED DEFINER=`jtechel`@`localhost` SQL SECURITY DEFINER VIEW `v_measurement_summary`  AS  select `s`.`site_name` AS `site_name`,`s`.`client_name` AS `client_name`,`s`.`elevator_count` AS `elevator_count`,`m`.`measurement_date` AS `measurement_date`,`m`.`measurer` AS `measurer`,count(`m`.`panel_number`) AS `panel_count`,group_concat(`m`.`panel_number` order by `m`.`panel_number` ASC separator ',') AS `panels_measured`,max(`m`.`created_at`) AS `latest_measurement` from (`elevator_sites` `s` left join `elevator_measurements` `m` on((`s`.`site_name` = `m`.`site_name`))) group by `s`.`site_name`,`m`.`measurement_date`,`m`.`measurer` order by max(`m`.`created_at`) desc ;

